<script lang="ts" setup>
import { computed, onMounted, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { getShopOperationStatistics, type ShopOperationStatistics } from '#/api/mall/statistics/shop';
import { getShopList, type MallShopApi } from '#/api/mall/product/shop';
const loading = ref(false); const rows = ref<ShopOperationStatistics[]>([]); const shops = ref<MallShopApi.Shop[]>([]); const shopId = ref<number>();
const totals = computed(() => rows.value.reduce((a, r) => ({ orders: a.orders + (r.orderCount || 0), paid: a.paid + (r.paidAmount || 0), refund: a.refund + (r.refundAmount || 0), settled: a.settled + (r.settledAmount || 0), unsettled: a.unsettled + (r.unsettledAmount || 0) }), { orders: 0, paid: 0, refund: 0, settled: 0, unsettled: 0 }));
async function refresh() { loading.value = true; try { rows.value = await getShopOperationStatistics(shopId.value ? { shopId: shopId.value } : undefined); } finally { loading.value = false; } }
onMounted(async () => { shops.value = await getShopList(); await refresh(); });
</script>
<template><Page auto-content-height><div class="p-4"><div class="mb-4 flex items-center gap-3"><span>统计店铺</span><select v-model="shopId" class="h-8 rounded border px-2" @change="refresh"><option :value="undefined">全部店铺</option><option v-for="shop in shops" :key="shop.id" :value="shop.id">{{ shop.name }}</option></select><button class="rounded bg-primary px-3 py-1 text-white" @click="refresh">刷新</button></div><div class="mb-4 grid grid-cols-5 gap-3"><div class="rounded bg-card p-3 shadow">订单数：{{ totals.orders }}</div><div class="rounded bg-card p-3 shadow">支付金额：{{ (totals.paid / 100).toFixed(2) }} 元</div><div class="rounded bg-card p-3 shadow">退款金额：{{ (totals.refund / 100).toFixed(2) }} 元</div><div class="rounded bg-card p-3 shadow">已结算：{{ (totals.settled / 100).toFixed(2) }} 元</div><div class="rounded bg-card p-3 shadow">待结算：{{ (totals.unsettled / 100).toFixed(2) }} 元</div></div><table class="w-full text-left text-sm"><thead><tr><th class="p-2">店铺</th><th class="p-2">订单数</th><th class="p-2">已支付订单</th><th class="p-2">支付金额</th><th class="p-2">退款金额</th><th class="p-2">已结算</th><th class="p-2">待结算</th></tr></thead><tbody><tr v-for="row in rows" :key="row.shopId" class="border-t"><td class="p-2">{{ row.shopName || '平台自营' }}</td><td class="p-2">{{ row.orderCount }}</td><td class="p-2">{{ row.paidOrderCount }}</td><td class="p-2">{{ ((row.paidAmount || 0) / 100).toFixed(2) }}</td><td class="p-2">{{ ((row.refundAmount || 0) / 100).toFixed(2) }}</td><td class="p-2">{{ ((row.settledAmount || 0) / 100).toFixed(2) }}</td><td class="p-2">{{ ((row.unsettledAmount || 0) / 100).toFixed(2) }}</td></tr><tr v-if="!loading && !rows.length"><td colspan="7" class="p-6 text-center text-gray-400">暂无数据</td></tr></tbody></table></div></Page></template>
